- (void)toggleChanged:(UISwitch*)s{[[NSNotificationCenter defaultCenter] postNotificationName:ZNMenuValueChangedNotification object:self userInfo:@{@"key":s.accessibilityIdentifier?:@"toggle",@"value":@(s.on)}];}
