- (void)toggleMenu{[self setMenuVisible:!self.menuVisible animated:YES];}
- (void)setMenuVisible:(BOOL)v animated:(BOOL)a{self.menuVisible=v;void(^changes)(void)=^{self.panel.alpha=v?1:0;self.panel.transform=v?CGAffineTransformIdentity:CGAffineTransformMakeScale(.96,.96);};if(!a){changes();self.panel.hidden=!v;return;}if(v)self.panel.hidden=NO;[UIView animateWithDuration:.2 delay:0 options:UIViewAnimationOptionCurveEaseOut|UIViewAnimationOptionBeginFromCurrentState animations:changes completion:^(BOOL f){if(!v)self.panel.hidden=YES;}];}
