- (__kindof UICollectionViewCell*)collectionView:(UICollectionView*)c cellForItemAtIndexPath:(NSIndexPath*)p{ZNPresetCell *x=[c dequeueReusableCellWithReuseIdentifier:@"preset" forIndexPath:p];[x setName:self.names[p.item] index:p.item];return x;}
